for (const item of $input.all()) {

  // Set default lead type
  item.json.lead_type = "Medium-Value";

  // High-value lead
  if (item.json.lead_score >= 3) {
    item.json.lead_type = "High-Value";
  }

  // Low-value lead
  if (item.json.lead_score < 1) {
    item.json.lead_type = "Low-Value";
  }

}

return $input.all();
